; players.asm -- chapter 35: two players, a joystick and the keys
; generated by gen35.py
        INCLUDE "msx.inc"
        OUTPUT "players.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
        INCLUDE "bios.inc"
ticks   EQU VARS                ; frames counted by isr
port1   EQU VARS + 1            ; register 14 of port 1
port2   EQU VARS + 2            ; and of port 2
r15     EQU VARS + 3            ; register 15, read back
r7      EQU VARS + 4            ; register 7, read back
way1    EQU VARS + 5            ; the directions
way2    EQU VARS + 6
bios    EQU VARS + 8            ; gtstck.asm: GTSTCK 1 and 2, GTTRIG 1 to 4
iff     EQU VARS + 14           ; gtstck.asm: 4 if the interrupts are on
pins    EQU VARS + 16           ; pins.asm: register 14 after each write
last1   EQU VARS + 8            ; each player's bits, the last frame
last2   EQU VARS + 9
fig1    EQU VARS + 16           ; the two figures: Y, X, pattern, colour
fig2    EQU VARS + 20
IM2_TABLE EQU $C200             ; 257 bytes of $C3: every vector is $C3C3
IM2_JUMP  EQU $C3C3             ; and there, a JP to the routine
; Two players: two figures, player 1 moved by joystick 1 and by the cursor
; keys, with SPACE for button A, player 2 by joystick 2. A pixel a frame for
; each switch held; each press of button A swaps the figure's two colours.
init:   di
        ld sp, SYS_AREA
        VDP_REG 1, $80          ; display off
        VDP_REG 0, $00          ; Graphic I
        VDP_REG 2, $06          ; names    $1800
        VDP_REG 3, $80          ; colours  $2000
        VDP_REG 4, $00          ; patterns $0000
        VDP_REG 5, $36          ; sprite attributes $1B00
        VDP_REG 6, $07          ; sprite patterns   $3800
        VDP_REG 7, $0F          ; border white
        VRAM_WRITE $0000        ; patterns: chapter 30's set at 32
        ld hl, shapes
        ld e, 4
        call send
        VRAM_WRITE $2000        ; black ink on white paper
        ld a, $1F
        ld b, 32
.col:   out (VDP_DATA), a
        djnz .col
        VRAM_WRITE $1800        ; the names
        ld hl, names
        ld e, 3
        call send
        VRAM_WRITE $1B00        ; no sprites
        ld a, $D0
        out (VDP_DATA), a
        VRAM_WRITE $3800        ; sprite pattern 0: chapter 26's figure
        ld hl, figure
        ld bc, 32 << 8 | VDP_DATA
        otir
        ld hl, fig1             ; figure 1: Y, X, pattern 0, its first colour
        ld (hl), 96
        inc hl
        ld (hl), 80
        inc hl
        ld (hl), 0
        inc hl
        ld (hl), 1
        ld hl, fig2             ; figure 2: Y, X, pattern 0, its first colour
        ld (hl), 96
        inc hl
        ld (hl), 160
        inc hl
        ld (hl), 0
        inc hl
        ld (hl), 7
        ld a, $FF
        ld (last1), a
        ld (last2), a
        ld hl, IM2_TABLE        ; mode 2: the table, 257 bytes of $C3
        ld de, IM2_TABLE + 1
        ld bc, 256
        ld (hl), high IM2_JUMP
        ldir
        ld a, $C3               ; and at $C3C3, JP isr
        ld (IM2_JUMP), a
        ld hl, isr
        ld (IM2_JUMP + 1), hl
        ld a, high IM2_TABLE
        ld i, a                 ; I: the page of the table
        im 2
        VDP_REG 1, $E2          ; the display on, the signal, sprites of 16 x 16
        in a, (VDP_CTRL)
main:   ei
        halt                    ; wait for the frame
        di                      ; the interrupts off: VDP, PSG and PPI
frame:  VRAM_WRITE $1B00        ; the two figures, in the lines not drawn
        ld hl, fig1
        ld bc, 8 << 8 | VDP_DATA
        otir
        ld a, $D0
        out (VDP_DATA), a
        call keys               ; player 1: the cursor keys and SPACE ...
        ld d, a
        xor a                   ; ... and joystick 1, together
        call joy
        and d
read:   ld ix, fig1
        ld hl, last1
        call move1
        ld a, $40               ; player 2: joystick 2
        call joy
        ld ix, fig2
        ld hl, last2
        call move2
        jp main

; keys: row 8 of the keyboard -> A in register 14's way: the cursor keys as
; the four switches, SPACE as button A, a 0 for each held. The interrupts
; must be off. Uses A, C, HL
keys:   in a, (PPI_C)           ; 12
        and $F0                 ;  8  port C's top bits kept (chapter 34)
        or 8                    ;  8
        out (PPI_C), a          ; 12  row 8
        in a, (PPI_B)           ; 12  bits 7-4: RIGHT DOWN UP LEFT; bit 0: SPACE
        ld c, a                 ;  5
        rrca                    ;  5
        rrca                    ;  5
        rrca                    ;  5
        rrca                    ;  5
        and $0F                 ;  8
        ld hl, kbdjoy           ; 11
        add a, l                ;  5
        ld l, a                 ;  5
        ld a, c                 ;  5
        and 1                   ;  8  SPACE
        rlca                    ;  5
        rlca                    ;  5
        rlca                    ;  5
        rlca                    ;  5  into bit 4, button A's
        or (hl)                 ;  8  and the cursor keys as the switches
        or $E0                  ;  8
        ret                     ; 11

; move1: A = a player's bits, a 0 for each switch held; IX = its figure's Y,
; X, pattern and colour; HL = its bits of the last frame. A pixel for each
; switch held, so that two opposite ones cancel; a press of A, held now and
; not the last frame, swaps the figure's two colours. Uses A, B, C
move1:  ld b, a
        ld c, (hl)              ; the last frame's bits
        ld (hl), a              ; this frame's, for the next
        rrca                    ; up
        jr c, .down
        dec (ix + 0)
.down:  rrca
        jr c, .left
        inc (ix + 0)
.left:  rrca
        jr c, .right
        dec (ix + 1)
.right: rrca
        jr c, .fire
        inc (ix + 1)
.fire:  ld a, b                 ; A: held now (a 0) and not before (a 1)
        cpl
        and c
        and $10
        ret z
        ld a, (ix + 3)          ; the other colour: the two XORed
        xor 5
        ld (ix + 3), a
        ret

; move2: A = a player's bits, a 0 for each switch held; IX = its figure's Y,
; X, pattern and colour; HL = its bits of the last frame. A pixel for each
; switch held, so that two opposite ones cancel; a press of A, held now and
; not the last frame, swaps the figure's two colours. Uses A, B, C
move2:  ld b, a
        ld c, (hl)              ; the last frame's bits
        ld (hl), a              ; this frame's, for the next
        rrca                    ; up
        jr c, .down
        dec (ix + 0)
.down:  rrca
        jr c, .left
        inc (ix + 0)
.left:  rrca
        jr c, .right
        dec (ix + 1)
.right: rrca
        jr c, .fire
        inc (ix + 1)
.fire:  ld a, b                 ; A: held now (a 0) and not before (a 1)
        cpl
        and c
        and $10
        ret z
        ld a, (ix + 3)          ; the other colour: the two XORed
        xor 3
        ld (ix + 3), a
        ret

; joy: A = $00 for port 1, $40 for port 2 -> A = that port's register 14, a 0
; for each switch closed. Register 15's other seven bits are kept. The
; interrupts must be off. Uses A, B
joy:    ld b, a                 ;  5
        ld a, 15                ;  8
        out (PSG_ADDR), a       ; 12  register 15
        in a, (PSG_READ)        ; 12  as it is
        and $BF                 ;  8  bit 6: the port
        or b                    ;  5
        out (PSG_WRITE), a      ; 12
        ld a, 14                ;  8
        out (PSG_ADDR), a       ; 12  register 14
        in a, (PSG_READ)        ; 12  the port's pins
        ret                     ; 11

; isr: every frame, a frame counted. Keeps AF
isr:    push af
        in a, (VDP_CTRL)        ; the status: the signal down
        ld a, (ticks)
        inc a
        ld (ticks), a
        pop af
        ei
        ret

; at: the next characters go to row D, column E (chapter 30)
at:     ld a, d
        rrca
        rrca
        rrca
        ld c, a
        and $E0
        or e
        out (VDP_CTRL), a
        ld a, c
        and $03
        or $18 | $40
        out (VDP_CTRL), a
        ret

; cells: A as eight boxes from bit 7, a filled box for a 0 (a key held) and
; an empty one for a 1, from the address set. Uses A, B, L
cells:  ld l, a
        ld b, 8
.cell:  ld a, 2
        rlc l                   ; the next bit, into the carry
        jr nc, .put             ; 0: held
        ld a, 1
.put:   out (VDP_DATA), a
        djnz .cell
        ret

; hex: A as two hexadecimal digits, from the address set. Uses A, C
hex:    ld c, a
        rrca
        rrca
        rrca
        rrca
        call .digit
        ld a, c
.digit: and $0F
        add a, '0'
        cp '9' + 1
        jr c, .out
        add a, 'A' - '9' - 1
.out:   out (VDP_DATA), a
        ret

; send: E blocks of 256 bytes from HL to the VDP
send:   ld c, VDP_DATA
        ld b, 0
.otir:  otir
        dec e
        jr nz, .otir
        ret
        ALIGN 16
